import os
from openai import OpenAI

def select_platform_resource(model_alias: str) -> str:
    # In a more complex scenario, this would map an alias to a specific deployment ID or fine-tuned model.
    # For OpenAI, the model_alias can directly be the model name.
    if model_alias == "default_chat":
        return "gpt-4o"
    elif model_alias == "fast_chat":
        return "gpt-3.5-turbo"
    else:
        return model_alias

import os
from openai import OpenAI

def collect_platform_metadata(prompt: str, model_name: str = "gpt-4o"):
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        organization=os.environ.get("OPENAI_ORGANIZATION_ID"),
    )
    response = client.chat.completions.create(
        model=model_name,
        messages=[{"role": "user", "content": prompt}]
    )

    content = response.choices[0].message.content
    metadata = {
        "id": response.id,
        "model": response.model,
        "usage": response.usage.model_dump() if response.usage else None,
        "finish_reason": response.choices[0].finish_reason
    }
    return {"content": content, "metadata": metadata}

import os
from openai import OpenAI

def get_openai_client():
    return OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        organization=os.environ.get("OPENAI_ORGANIZATION_ID"),
    )

from typing import Dict, Any

def create_chat_request(prompt: str, model_name: str = "gpt-4o") -> Dict[str, Any]:
    return {
        "model": model_name,
        "messages": [{"role": "user", "content": prompt}]
    }

def normalize_chat_response(response: Any) -> Dict[str, Any]:
    if hasattr(response, 'choices') and response.choices:
        content = response.choices[0].message.content
        metadata = {
            "id": response.id,
            "model": response.model,
            "usage": response.usage.model_dump() if hasattr(response, 'usage') and response.usage else None,
            "finish_reason": response.choices[0].finish_reason if response.choices[0].finish_reason else None
        }
        return {"content": content, "metadata": metadata}
    return {"content": "", "metadata": {}}

import os
from openai import OpenAI

def localized_platform_output(text: str, target_language: str = "French"):
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        organization=os.environ.get("OPENAI_ORGANIZATION_ID"),
    )
    response = client.chat.completions.create(
        model="gpt-4o",
        messages=[
            {"role": "system", "content": f"Translate the following text into {target_language}."},
            {"role": "user", "content": text}
        ]
    )
    return response.choices[0].message.content
